#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

WORKER_NAME="weekend-deals"

# Wrangler from the project, so it finds wrangler.jsonc.
wr() { (cd "$PROJECT_DIR" && npx --no-install wrangler "$@"); }

# put_secret NAME VALUE stores a value on the Worker; it goes in through stdin, so it is never shown.
put_secret() {
  local name="$1" value="$2" output
  if output=$(printf '%s' "$value" | wr secret put "$name" 2>&1); then
    printf '  %s✓ geheim%s %s → Cloudflare\n' "$GREEN" "$RESET" "$name"
  else
    warn "$name niet opgeslagen: $(printf '%s' "$output" | tail -n 2)"
    SKIPPED+=("geheim $name: start dit script opnieuw")
  fi
}

# Cloudflare for this project is signed in in Microsoft Edge; in another browser its login fails for lack of a
# session cookie. Falls back to the default browser where Edge is missing.
EDGE_APP="/Applications/Microsoft Edge.app"
open_in_edge() {
  if [[ -d "$EDGE_APP" ]]; then
    printf '  %s↗ opening in Edge%s %s\n' "$GREEN" "$RESET" "$1"
    open -a "$EDGE_APP" "$1"
  else
    open_url "$1"
  fi
}

# Wrangler would open the default browser itself; it only prints the link here, which then opens in Edge.
wrangler_login() {
  local log url="" pid
  log=$(mktemp)
  (cd "$PROJECT_DIR" && npx --no-install wrangler login --browser=false) >"$log" 2>&1 &
  pid=$!
  for _ in $(seq 1 30); do
    url=$(grep -oE 'https://dash\.cloudflare\.com/oauth2/auth[^[:space:]]+' "$log" | head -n1 || true)
    [[ -n "$url" ]] && break
    sleep 1
  done
  if [[ -z "$url" ]]; then
    cat "$log"
    kill "$pid" 2>/dev/null || true
    rm -f "$log"
    return 1
  fi
  open_in_edge "$url"
  say "Log in en klik op 'Allow'; daarna gaat dit script vanzelf verder."
  wait "$pid" || true
  grep -iE "success|error" "$log" | sed 's/^/  /' || true
  rm -f "$log"
}

run_wizard() {

TOTAL_STAGES=6
ENV_FILE="$(cd "$(dirname "$0")/.." && pwd)/.env.local"
PROJECT_DIR="$(cd "$(dirname "$0")/.." && pwd)"

banner "Cloudflare: Weekendje weg in de cloud, alleen voor jou"

stage "Turso klaar?"
say "De cloud-app leest de prijzen uit Turso. Die gegevens staan na scripts/setup-turso.sh in .env.local."
TURSO_DATABASE_URL=$(_existing TURSO_DATABASE_URL || true)
TURSO_AUTH_TOKEN=$(_existing TURSO_AUTH_TOKEN || true)
if [[ -z "$TURSO_DATABASE_URL" || -z "$TURSO_AUTH_TOKEN" ]]; then
  warn "Turso is nog niet ingesteld. Draai eerst: bash scripts/setup-turso.sh"
  exit 1
fi
printf '  %s✓ Turso-gegevens gevonden%s\n' "$GREEN" "$RESET"
pause "Druk op Enter."

stage "Inloggen bij Cloudflare"
WHOAMI=$(wr whoami 2>&1 || true)
if grep -qi "not authenticated" <<<"$WHOAMI"; then
  say "De inlogpagina van Cloudflare opent in Edge, waar je voor dit project bent ingelogd."
  pause "Druk op Enter om Edge te openen."
  wrangler_login || true
  WHOAMI=$(wr whoami 2>&1 || true)
  while grep -qi "not authenticated" <<<"$WHOAMI"; do
    warn "Inloggen bij Cloudflare is nog niet gelukt."
    confirm "Opnieuw proberen?" || exit 1
    wrangler_login || true
    WHOAMI=$(wr whoami 2>&1 || true)
  done
  printf '  %s✓ Ingelogd bij Cloudflare%s\n' "$GREEN" "$RESET"
fi
ACCOUNTS=$(grep -oE '\b[0-9a-f]{32}\b' <<<"$WHOAMI" | sort -u || true)
if [[ $(grep -c . <<<"$ACCOUNTS") -eq 1 ]]; then
  write_env CLOUDFLARE_ACCOUNT_ID "$ACCOUNTS"
else
  grep -E '│|\|' <<<"$WHOAMI" || true
  say "Je hebt meer dan één Cloudflare-account. Kies het account voor deze app."
  until ask CLOUDFLARE_ACCOUNT_ID "Account ID (32 tekens uit de tabel):" && [[ "$CLOUDFLARE_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; do
    warn "Dat is geen account-ID uit de tabel."
  done
  write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
fi
export CLOUDFLARE_ACCOUNT_ID
pause "Druk op Enter."

stage "App bouwen en uploaden"
say "Het script bouwt de app en zet hem als Worker bij Cloudflare (gratis plan)."
note "Vraagt Wrangler om een workers.dev-subdomein te kiezen, kies dan iets wat je herkent."
DEPLOY_LOG=$(mktemp)
(cd "$PROJECT_DIR" && npm run -s build)
# script(1) keeps the terminal, so Wrangler can still ask questions, and keeps a copy of what it printed.
(cd "$PROJECT_DIR" && script -q "$DEPLOY_LOG" npx --no-install wrangler deploy)
WORKER_URL=$(grep -oE "https://${WORKER_NAME}\.[A-Za-z0-9-]+\.workers\.dev" "$DEPLOY_LOG" | head -n1 || true)
rm -f "$DEPLOY_LOG"
if [[ -z "$WORKER_URL" ]]; then
  say "Kopieer het https://…workers.dev-adres dat Wrangler hierboven toonde."
  until ask WORKER_URL "Adres van de app:" && [[ "$WORKER_URL" =~ ^https://.+\.workers\.dev/?$ ]]; do
    warn "Dat lijkt geen workers.dev-adres."
  done
fi
write_env WORKER_URL "${WORKER_URL%/}"
pause "Druk op Enter."

stage "Turso koppelen"
say "De Worker krijgt het adres en de sleutel van je database als geheim; ze komen niet in de code."
put_secret TURSO_DATABASE_URL "$TURSO_DATABASE_URL"
put_secret TURSO_AUTH_TOKEN "$TURSO_AUTH_TOKEN"
pause "Druk op Enter."

stage "Alleen jij erbij: Cloudflare Access"
say "Cloudflare Access zet een inlogscherm voor de app: alleen jouw e-mailadres komt erin (gratis tot 50 gebruikers)."
say "Tot die tijd geeft de app geen gegevens prijs."
open_in_edge "https://dash.cloudflare.com/${CLOUDFLARE_ACCOUNT_ID}/workers/services/view/${WORKER_NAME}/production/settings"
step "Ga naar 'Domains & Routes' en zet bij de workers.dev-regel Cloudflare Access aan."
step "Nog geen Zero Trust-team? Kies dan een teamnaam en het Free-plan."
step "Controleer de toegangsregel (policy): alleen jouw e-mailadres."
step "Kopieer de 'Audience (AUD) tag' en de JWKS-URL (eindigt op /cdn-cgi/access/certs)."
note "Later terugvinden: Zero Trust → Access → Applications → de app van ${WORKER_NAME}."
until ask ACCESS_TEAM_DOMAIN "JWKS-URL of teamdomein (…cloudflareaccess.com):" \
  && ACCESS_TEAM_DOMAIN=$(printf '%s' "$ACCESS_TEAM_DOMAIN" | sed -E 's#^[[:space:]]*https?://##; s#/.*$##; s#[[:space:]]*$##') \
  && [[ "$ACCESS_TEAM_DOMAIN" =~ ^[a-z0-9-]+\.cloudflareaccess\.com$ ]]; do
  warn "Verwacht iets als jouwteam.cloudflareaccess.com."
done
until ask ACCESS_AUD "Audience (AUD) tag:" && [[ "$ACCESS_AUD" =~ ^[0-9a-f]{64}$ ]]; do
  warn "De AUD-tag is 64 tekens (0-9, a-f)."
done
write_env ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
write_env ACCESS_AUD "$ACCESS_AUD"
put_secret ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
put_secret ACCESS_AUD "$ACCESS_AUD"
pause "Druk op Enter."

stage "Testen"
CHECK=$(curl -s -o /dev/null -w '%{http_code} %{redirect_url}' "$WORKER_URL/api/status" || true)
if [[ "$CHECK" == 302*cloudflareaccess.com* ]]; then
  printf '  %s✓ Zonder inloggen stuurt Cloudflare naar het inlogscherm%s\n' "$GREEN" "$RESET"
else
  warn "Cloudflare Access lijkt nog niet aan te staan (antwoord: ${CHECK%% *}). De gegevens blijven dicht,"
  warn "maar de app werkt pas als Access aanstaat. Controleer stap 5 en start dit script opnieuw."
  SKIPPED+=("Cloudflare Access aanzetten voor ${WORKER_URL}")
fi
say "Open de app, log in met de code die Cloudflare je mailt, en kijk of de deals verschijnen."
open_in_edge "$WORKER_URL"
pause "Druk op Enter."

finish
say "Je app: ${WORKER_URL}"
say "Nieuwe versie uploaden: npm run cloud:deploy"
say "De ververs-knop in de cloud vraagt een ronde aan bij je Mac. Zet daarvoor eenmalig: npm run background:on"
printf '\n'
}

run_wizard "$@"; exit
